const raw = $json.body || {};
let b = raw;
try { if (typeof raw === 'string') b = JSON.parse(raw); } catch (_) { return []; }
const clean = (value, limit = 500) => String(value || '').trim().replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, limit);
const email = clean(b.email, 254).toLowerCase();
const allowedProcesses = new Set(['Rechnungseingang und Belege', 'Postfach und Kundenanfragen', 'Angebots- oder Lead-Nachfassung', 'Anderer Büroprozess']);
const privacyAcknowledged = ['on', 'true', '1', true].includes(b.datenschutz_kenntnis);
if (b.event !== 'sprint_lead' || b.form !== 'kontaktformular' || !email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !allowedProcesses.has(b.prozess) || !privacyAcknowledged || clean(b.honeypot)) return [];
const name = clean(b.name, 160);
const company = clean(b.firma, 160) || name;
if (!name || !company || !clean(b.nachricht, 4000)) return [];
const notes = [
  'Quelle: ' + (clean(b.quelle, 120) || 'Website / Prozess-Check'),
  'Angebot: ' + (clean(b.angebot, 120) || 'Automation Sprint'),
  'Name: ' + name,
  'E-Mail: ' + email,
  'Prozess: ' + clean(b.prozess, 160),
  'Nachricht: ' + clean(b.nachricht, 4000),
  'Eingang: ' + clean(b.submitted_at, 80),
  'Seite: ' + clean(b.page, 500)
];
const phone = clean(b.telefon, 80);
if (phone) notes.splice(4, 0, 'Telefon: ' + phone);
return { fields: { Company: ('Inbound · ' + company).slice(0, 255), Branch: 'Website-Anfrage', Region: 'Berlin & Brandenburg', Website: clean(b.page, 500), Phone: phone, Status: 'Neu', Potential_Score: 10, Notes: notes.join('\n') } };
